package io.invenlio.inventory;
import jakarta.servlet.http.*;import java.net.*;import java.util.*;import org.slf4j.MDC;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice class InventoryExceptionHandler{@ExceptionHandler(InventoryException.class)ResponseEntity<ProblemDetail>handle(InventoryException e,HttpServletRequest r){HttpStatus s=e.code().endsWith("NOT_FOUND")?HttpStatus.NOT_FOUND:Set.of("INSUFFICIENT_ON_HAND","IDEMPOTENCY_KEY_REUSED","CONCURRENT_INVENTORY_MODIFICATION").contains(e.code())?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;ProblemDetail p=ProblemDetail.forStatusAndDetail(s,e.getMessage());p.setType(URI.create("https://invenlio.io/problems/"+e.code().toLowerCase().replace('_','-')));p.setTitle(s.getReasonPhrase());p.setInstance(URI.create(r.getRequestURI()));p.setProperty("code",e.code());p.setProperty("correlationId",MDC.get("correlationId"));return ResponseEntity.status(s).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}}
